/* Ledgerly home dashboard mocks. Shared tokens and tiles; variants add a body class. */

:root {
  color-scheme: light;
  /* colour: restrained, neutrals tinted toward hue 250, one accent */
  --page:      oklch(0.962 0.008 250);
  --tile:      oklch(0.995 0.002 250);
  --ink:       oklch(0.25 0.02 255);
  --ink-2:     oklch(0.45 0.02 255);
  --hair:      oklch(0.89 0.01 250);
  --accent:    oklch(0.48 0.15 255);
  --on-accent: oklch(0.99 0 0);
  --ring:      oklch(0.48 0.15 255);
  /* meter (dataviz: track is a lighter step of the fill's ramp) */
  --track:     oklch(0.91 0.03 250);
  --fill:      oklch(0.55 0.12 250);
  --over:      oklch(0.62 0.17 45);
  --over-ink:  oklch(0.48 0.15 40);
  --short:     oklch(0.88 0.06 55);

  /* type: fixed rem scale, ratio 1.2 (product register) */
  --t-sm: 0.875rem;
  --t-base: 1rem;
  --t-md: 1.2rem;
  --t-lg: 1.44rem;
  --t-xl: 1.728rem;
  --t-hero: 3rem;

  /* space: 4/8/12/16/24/40 */
  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;

  --r-tile: 1rem;
  --r-ctl: 0.5rem;

  --pace: 35.48%; /* day 11 of 31 */
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--page);
  color: var(--ink);
  font: 400 var(--t-base)/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}

::selection { background: oklch(0.85 0.07 250); }

a { color: inherit; }

:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap;
}

.skip {
  position: absolute; inset-inline-start: var(--s4); top: -3rem;
  background: var(--tile); padding: var(--s2) var(--s3); border-radius: var(--r-ctl);
}
.skip:focus { top: var(--s2); }

.mock-note {
  margin: 0; padding: var(--s2) var(--s4);
  background: var(--ink); color: var(--tile);
  font-size: var(--t-sm); text-align: center;
}

/* ---------- app chrome ---------- */

.topbar {
  display: flex; flex-wrap: wrap; align-items: center; gap: var(--s3) var(--s5);
  max-width: 80rem; margin: 0 auto; padding: var(--s4) var(--s5);
}

.wordmark {
  font-weight: 700; font-size: var(--t-md); letter-spacing: -0.01em;
  text-decoration: none;
}

.nav ul { display: flex; flex-wrap: wrap; gap: var(--s1); margin: 0; padding: 0; list-style: none; }
.nav a {
  display: block; padding: var(--s2) var(--s3); border-radius: var(--r-ctl);
  color: var(--ink-2); text-decoration: none; font-weight: 500;
}
.nav a[aria-current="page"] { color: var(--accent); background: oklch(0.93 0.03 255); }
@media (hover: hover) {
  .nav a:hover { color: var(--ink); background: oklch(0.93 0.01 250); }
}

.btn {
  margin-inline-start: auto;
  display: inline-flex; align-items: center; gap: var(--s2);
  min-height: 2.5rem; padding: 0 var(--s4);
  border: 0; border-radius: var(--r-ctl);
  background: var(--accent); color: var(--on-accent);
  font: 600 var(--t-base)/1 inherit; font-family: inherit;
  cursor: pointer; touch-action: manipulation;
}
.btn:active { background: oklch(0.40 0.14 255); }
@media (hover: hover) { .btn:hover { background: oklch(0.44 0.15 255); } }
.btn svg { width: 1.125rem; height: 1.125rem; }

/* ---------- page ---------- */

main { max-width: 80rem; margin: 0 auto; padding: var(--s2) var(--s5) var(--s6); }

.page-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--s2) var(--s4); margin-block: var(--s4) var(--s5); }
.page-head h1 { margin: 0; font-size: var(--t-xl); line-height: 1.2; letter-spacing: -0.015em; }
.page-head p { margin: 0; color: var(--ink-2); }

/* ---------- bento ---------- */

.bento {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: var(--s4);
}

.tile {
  min-width: 0;
  background: var(--tile);
  border: 1px solid var(--hair);
  border-radius: var(--r-tile);
  padding: var(--s5);
}
.tile h2 { margin: 0; font-size: var(--t-md); line-height: 1.3; }
.tile-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: var(--s1) var(--s4); }
.tile-head a { font-size: var(--t-sm); font-weight: 500; color: var(--accent); text-underline-offset: 0.2em; }

.t-balance { grid-column: 1 / span 5; }
.t-spend   { grid-column: 6 / span 7; grid-row: 1 / span 2; }
.t-goals   { grid-column: 1 / span 5; }
.t-bills   { grid-column: 1 / -1; }

@media (max-width: 60rem) {
  .bento > .tile { grid-column: 1 / -1; grid-row: auto; }
}
@media (max-width: 30rem) {
  main, .topbar { padding-inline: var(--s3); }
  .tile { padding: var(--s4); }
}

.muted { color: var(--ink-2); }
.num { font-variant-numeric: tabular-nums; }
.small { font-size: var(--t-sm); }

/* ---------- balance ---------- */

.hero { margin: var(--s3) 0 0; font-size: var(--t-hero); font-weight: 650; line-height: 1.05; letter-spacing: -0.03em; }
.hero-sub { margin: var(--s2) 0 var(--s5); color: var(--ink-2); }

.sum { margin: 0; display: grid; grid-template-columns: 1fr auto; gap: var(--s2) var(--s4); font-variant-numeric: tabular-nums; }
.sum dt { color: var(--ink-2); }
.sum dd { margin: 0; text-align: end; }
.sum .total { padding-top: var(--s2); border-top: 1px solid var(--hair); color: var(--ink); font-weight: 600; }

/* ---------- the signature: meter with today tick ---------- */

.meter {
  position: relative; height: 0.5rem; margin-block: var(--s2);
  background: var(--track); border-radius: 2px;
}
.meter .fill, .meter .over, .meter .gap {
  position: absolute; top: 0; bottom: 0;
}
.meter .fill { left: 0; background: var(--fill); border-radius: 0 4px 4px 0; }
.meter .over { background: var(--over); border-radius: 0 4px 4px 0; }
.meter .gap  { background: var(--short); }
.meter .tick {
  position: absolute; top: -0.3125rem; bottom: -0.3125rem; width: 2px;
  left: var(--at, var(--pace)); margin-left: -1px;
  background: var(--ink);
  box-shadow: 0 0 0 2px var(--tile); /* dataviz surface ring */
}

.status { display: inline-flex; align-items: center; gap: var(--s1); }
.status svg { width: 1rem; height: 1rem; flex: none; }
.status.warn { color: var(--over-ink); font-weight: 600; }

.key { display: flex; align-items: center; gap: var(--s2); margin: var(--s2) 0 0; font-size: var(--t-sm); color: var(--ink-2); }
.key i { display: inline-block; width: 2px; height: 0.875rem; background: var(--ink); }

/* ---------- spending ---------- */

.spend-total { margin: var(--s3) 0 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--s1) var(--s3); }
.spend-total strong { font-size: var(--t-xl); font-weight: 650; letter-spacing: -0.02em; }

.cats { list-style: none; margin: var(--s5) 0 0; padding: 0; display: grid; gap: var(--s4); }
.cat { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 var(--s4); }
.cat .name { font-weight: 550; }
.cat .amt { text-align: end; font-variant-numeric: tabular-nums; }
.cat .meter { grid-column: 1 / -1; }
.cat .status { grid-column: 1 / -1; font-size: var(--t-sm); color: var(--ink-2); }
.cat .status.warn { color: var(--over-ink); }

/* ---------- goals ---------- */

.goals { list-style: none; margin: var(--s4) 0 0; padding: 0; display: grid; gap: var(--s4); }
.goal { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 var(--s4); }
.goal .name { font-weight: 550; }
.goal .amt { text-align: end; font-variant-numeric: tabular-nums; }
.goal .meter, .goal .status { grid-column: 1 / -1; }
.goal .status { font-size: var(--t-sm); color: var(--ink-2); }

/* ---------- bills ---------- */

.bills-body { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: var(--s5) var(--s6); margin-top: var(--s4); }
@media (max-width: 60rem) { .bills-body { grid-template-columns: minmax(0, 1fr); } }

.strip { position: relative; padding-top: 2.25rem; padding-bottom: 1.75rem; }
.strip .meter { height: 0.75rem; }
.strip .elapsed { position: absolute; left: 0; top: 0; bottom: 0; width: var(--pace); background: oklch(0.80 0.05 250); border-radius: 2px 0 0 2px; }
.strip .pin {
  position: absolute; top: 50%; width: 0.75rem; height: 0.75rem; margin: -0.375rem 0 0 -0.375rem;
  left: var(--at); border-radius: 50%;
  background: var(--fill); box-shadow: 0 0 0 2px var(--tile);
}
.strip .pin.big { width: 1rem; height: 1rem; margin: -0.5rem 0 0 -0.5rem; }
.strip .flag {
  position: absolute; left: var(--at); transform: translateX(-50%);
  font-size: var(--t-sm); white-space: nowrap;
}
.strip .flag.top { top: 0; font-weight: 600; }
.strip .flag.bottom { bottom: 0; color: var(--ink-2); }
.strip .payday { position: absolute; top: -0.3125rem; bottom: -0.3125rem; width: 2px; left: var(--at); margin-left: -1px; background: var(--ink-2); }
.strip .axis { display: flex; justify-content: space-between; font-size: var(--t-sm); color: var(--ink-2); margin-top: var(--s2); }

.bill-list { list-style: none; margin: 0; padding: 0; }
.bill { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 var(--s4); padding-block: var(--s3); border-top: 1px solid var(--hair); }
.bill:first-child { border-top: 0; padding-top: 0; }
.bill .name { font-weight: 550; overflow-wrap: anywhere; }
.bill .amt { text-align: end; font-variant-numeric: tabular-nums; font-weight: 550; }
.bill .when { font-size: var(--t-sm); color: var(--ink-2); }
.bill .auto { font-size: var(--t-sm); color: var(--ink-2); text-align: end; }

