const o=(L,C,H)=>{const h=H*Math.PI/180,a=C*Math.cos(h),b=C*Math.sin(h);
  const l=(L+0.3963377774*a+0.2158037573*b)**3, m=(L-0.1055613458*a-0.0638541728*b)**3,
        s=(L-0.0894841775*a-1.2914855480*b)**3;
  return [4.0767416621*l-3.3077115913*m+0.2309699292*s,-1.2684380046*l+2.6097574011*m-0.3413193965*s,
          -0.0041960863*l-0.7034186147*m+1.7076147010*s].map(v=>Math.round(Math.min(1,Math.max(0,f(v)))*255));};
const lum=(c)=>{c=c.map(v=>{v/=255;return v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4;});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];};
const r=(A,B)=>{const [x,y]=[lum(A),lum(B)].sort((p,q)=>q-p);return +((x+0.05)/(y+0.05)).toFixed(2);};
const T={page:o(.962,.008,250),tile:o(.995,.002,250),ink:o(.25,.02,255),ink2:o(.45,.02,255),accent:o(.48,.15,255),
 onacc:o(.99,0,0),track:o(.91,.03,250),fill:o(.55,.12,250),over:o(.62,.17,45),overink:o(.48,.15,40),short:o(.88,.06,55),
 navbg:o(.93,.03,255),elapsed:o(.80,.05,250)};
const P=[['ink/tile','ink','tile',4.5],['ink2/tile','ink2','tile',4.5],['ink2/page','ink2','page',4.5],['accent link/tile','accent','tile',4.5],
['accent nav/navbg','accent','navbg',4.5],['onaccent/accent btn','onacc','accent',4.5],['overink/tile','overink','tile',4.5],
['ring/page','accent','page',3],['ring/tile','accent','tile',3],['fill/track','fill','track',3],['over/track','over','track',3],['over/tile','over','tile',3],
['fill/tile','fill','tile',3],['tick ink/track','ink','track',3],['tick ink/over','ink','over',3],['tick ink/fill','ink','fill',3],['short/track','short','track',1],['pin fill/elapsed','fill','elapsed',3],['pin fill/track','fill','track',3],['ink2 payday/track','ink2','track',3]];
for(const [n,a,b,min] of P){const v=r(T[a],T[b]);console.log((v>=min?'PASS':'FAIL').padEnd(5),n.padEnd(22),v,'>=',min);}

